const KEY="minmaxTrackerV2";
const defaults={week:1,day:0,active:false,session:null,history:[],lastPage:"home",rest:{running:false,end:0,seconds:0,display:"normal"},draft:{}};
let state=load();
function load(){try{return Object.assign({},defaults,JSON.parse(localStorage.getItem(KEY)||"null")||{})}catch(e){return JSON.parse(JSON.stringify(defaults))}}
function save(){localStorage.setItem(KEY,JSON.stringify(state));}
function toast(msg){const e=document.getElementById('toast');e.textContent=msg;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),1700)}
function esc(s){return String(s??'').replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[m]))}
function fmtTime(sec){sec=Math.max(0,Math.floor(sec));const h=Math.floor(sec/3600),m=Math.floor(sec%3600/60),s=sec%60;return h?`${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`:`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
function weekDays(w){return PROGRAM[String(w)].days}
function currentDay(){return weekDays(state.week)[state.day]||weekDays(state.week)[0]}
function page(title,sub,body,active='home'){document.getElementById('app').innerHTML=`<div class="app"><header class="top"><div class="brand">MIN-MAX</div><div class="sub">${esc(sub||'12-Week Workout Tracker')}</div></header><main class="screen">${body}</main>${nav(active)}</div>`;}
function nav(active){return `<nav class="nav"><div class="nav-inner"><button class="${active==='home'?'active':''}" onclick="go('home')"><span class="nav-icon">⌂</span><span class="nav-label">Home</span></button><button class="${active==='workout'?'active':''}" onclick="go('workout')"><span class="nav-icon">✓</span><span class="nav-label">Workout</span></button><button class="${active==='progress'?'active':''}" onclick="go('progress')"><span class="nav-icon">↗</span><span class="nav-label">Progress</span></button><button class="${active==='program'?'active':''}" onclick="go('program')"><span class="nav-icon">☷</span><span class="nav-label">Program</span></button><button class="${active==='info'?'active':''}" onclick="go('info')"><span class="nav-icon">ⓘ</span><span class="nav-label">Info</span></button></div></nav>`}
function go(p){state.lastPage=p;save(); if(p==='home')home(); if(p==='workout')workout(); if(p==='progress')progress(); if(p==='program')programPage(); if(p==='info')infoPage();}
function home(){const d=currentDay();const hist=state.history||[];const total=hist.length;const last=hist[hist.length-1];const weekPct=Math.round((state.week/12)*100);page('','',`<section class="hero"><div class="eyebrow">Block ${PROGRAM[String(state.week)].block} · Week ${state.week}</div><h1>${esc(d.name)}</h1><div class="muted">${d.exercises.length} exercises · 12-week Min-Max program</div><div class="progressbar"><div style="width:${weekPct}%"></div></div><div class="actions" style="margin-top:16px"><button class="btn" onclick="startWorkout()">${state.active?'RESUME WORKOUT':'START WORKOUT'} →</button><button class="btn secondary" onclick="programPage()">VIEW PROGRAM</button></div></section><div class="grid"><div class="card"><div class="stat">WORKOUTS LOGGED</div><div class="big">${total}</div></div><div class="card"><div class="stat">LAST SESSION</div><div class="big" style="font-size:18px">${last?fmtDate(last.date):'—'}</div></div></div><div class="section-title"><h2>Week ${state.week}</h2><button class="smallbtn" onclick="chooseWeek()">Change</button></div><div class="list">${weekDays(state.week).map((x,i)=>`<div class="day-card" onclick="selectDay(${i})"><div><div class="name">Day ${i+1} · ${esc(x.name)}</div><div class="meta">${x.exercises.length} exercises</div></div><span class="pill">${i===state.day?'TODAY':'OPEN'}</span></div>`).join('')}</div>`,'home') }
function chooseWeek(){const options=Array.from({length:12},(_,i)=>`<option value="${i+1}" ${state.week===i+1?'selected':''}>Week ${i+1} · Block ${i<6?1:2}</option>`).join('');showModal(`<button class="close" onclick="closeModal()">×</button><h2>Select Week</h2><select class="week-select" id="mw">${options}</select><button class="btn full" style="margin-top:12px" onclick="setWeek()">Save Week</button>`)}
function setWeek(){state.week=+document.getElementById('mw').value;state.day=0;save();closeModal();home();}
function selectDay(i){state.day=i;save();startWorkout();}
function startWorkout(){const d=currentDay();if(!state.active){state.active=true;state.session={id:Date.now(),week:state.week,day:state.day,name:d.name,start:null,end:null,started:false,paused:false,pausedAt:null,elapsedAccum:0,sets:{},notes:''};save();}else if(state.session.paused){resumeWorkout();return}workout();}
function beginWorkout(){const s=state.session;if(!s||s.started)return;s.started=true;s.start=Date.now();s.paused=false;s.pausedAt=null;primeAudio();save();workout();toast('Workout started');}
function workoutElapsed(){const s=state.session;if(!s||!s.started)return 0;return Math.floor((s.elapsedAccum||0)+(s.paused?0:(Date.now()-s.start)/1000));}
function pauseWorkout(){const s=state.session;if(!s||!s.started||s.paused)return;s.pausedAt=Date.now();s.elapsedAccum=(s.elapsedAccum||0)+(s.pausedAt-s.start)/1000; s.paused=true;save();clearInterval(window.sessionTimer);workout();toast('Workout paused');}
function resumeWorkout(){const s=state.session;if(!s||!s.paused)return;s.start=Date.now();s.paused=false;s.pausedAt=null;primeAudio();save();workout();toast('Workout resumed');}
function resetWorkout(){if(!state.session)return;if(confirm('Reset this workout? All entries from this unfinished session will be discarded.')){state.active=false;state.session=null;state.rest={running:false,end:0,seconds:0,display:state.rest.display||'normal'};save();clearInterval(window.sessionTimer);clearInterval(window.restTimer);toast('Workout reset');setTimeout(()=>go('home'),200)}}
function workout(){const d=currentDay();if(!state.active||!state.session){startWorkout();return}const s=state.session;const elapsed=workoutElapsed();const startButton=!s.started?`<button class="btn start-workout-btn" onclick="beginWorkout()">▶ START WORKOUT</button>`:'';const pauseButton=s.started?`<button class="btn secondary" onclick="${s.paused?'resumeWorkout()':'pauseWorkout()'}">${s.paused?'▶ RESUME':'Ⅱ PAUSE'}</button>`:'';page('','Week '+state.week+' · '+d.name,`<div class="workout-tools"><div class="actions">${startButton}<button class="btn info-btn" onclick="openInfoLookup()">ⓘ INFO / LOOKUP</button>${pauseButton}<button class="btn ghost" onclick="finishWorkout()">FINISH WORKOUT</button><button class="btn ghost" onclick="resetWorkout()">RESET</button><button class="btn ghost" onclick="historyPage()">HISTORY</button></div></div><div class="card" style="margin-bottom:12px"><div class="stat">WORKOUT TIME ${!s.started?'· NOT STARTED':s.paused?'· PAUSED':''}</div><div class="big" id="sessionClock">${fmtTime(elapsed)}</div><div class="stat" style="margin-top:4px">Week ${state.week} · Day ${state.day+1} · ${Object.values(s.sets||{}).filter(x=>x.done).length} sets completed</div></div>${!s.started?'<div class="pause-banner">Workout is ready. Your timer will stay at 00:00 until you press START WORKOUT.</div>':''}${s.paused?'<div class="pause-banner">Workout paused. Your workout time is frozen until you resume.</div>':''}${d.exercises.map((ex,idx)=>exerciseCard(ex,idx)).join('')}${restBar()}`,'workout');if(s.started&&!s.paused)startSessionTicker();else clearInterval(window.sessionTimer);startRestTicker();}
function keyFor(exIdx,setIdx){return `${state.week}-${state.day}-${exIdx}-${setIdx}`}
function getDraft(exIdx,setIdx){const k=keyFor(exIdx,setIdx);return state.session?.sets?.[k]||{weight:'',reps:'',rir:''}}
function prevFor(name){for(let i=state.history.length-1;i>=0;i--){const h=state.history[i];for(const k in h.sets||{}){const x=h.sets[k];if(x.exercise===name && x.weight!=='' ) return x;}}return null}
function exerciseCard(ex,idx){const prev=prevFor(ex.exercise);const rr=ex.repRange;let rows='';for(let n=0;n<ex.sets;n++){const v=getDraft(idx,n);rows+=`<div class="set-row ${v.done?'completed':''}"><div class="setnum">${n+1}</div><div class="field"><label>Weight</label><input inputmode="decimal" value="${esc(v.weight)}" placeholder="${prev?.weight||'—'}" onchange="setVal(${idx},${n},'weight',this.value)"></div><div class="field"><label>Reps</label><input inputmode="numeric" value="${esc(v.reps)}" placeholder="${rr==='N/A'?'sec':rr}" onchange="setVal(${idx},${n},'reps',this.value)"></div><div class="field"><label>RIR</label><select onchange="setVal(${idx},${n},'rir',this.value)"><option value="">—</option>${[0,1,2,3,4,5].map(x=>`<option value="${x}" ${String(v.rir)===String(x)?'selected':''}>${x}</option>`).join('')}</select></div></div>${v.done?'<div class="set-complete done">✓ SET COMPLETE · REST RUNNING</div>':''}`}return `<section class="exercise"><div class="exercise-head"><div><h3>${idx+1}. ${esc(ex.exercise)}</h3><div class="target">${ex.sets} working set${ex.sets>1?'s':''} · ${esc(rr)} reps · Target RIR ${esc(ex.rir)} · Rest ${esc(ex.rest)}</div></div><span class="pill">WU ${esc(ex.wu)}</span></div>${ex.intensity!=='N/A'?`<div class="intensity">⚡ ${esc(ex.intensity)}</div>`:''}${rows}<div class="actions exercise-actions" style="margin-top:10px"><button class="smallbtn" onclick="startRest('${ex.rest}')">START REST</button><button class="smallbtn" onclick="historyExercise('${esc(ex.exercise)}')">HISTORY</button>${VIDEO_LINKS[ex.exercise]?`<a class="smallbtn video-btn" href="${VIDEO_LINKS[ex.exercise]}" target="_blank" rel="noopener noreferrer">▶ VIDEO</a>`:''}</div></section>`}
function setVal(e,s,field,val){if(!state.session.sets)state.session.sets={};const k=keyFor(e,s);const ex=currentDay().exercises[e];if(!state.session.sets[k])state.session.sets[k]={exercise:ex.exercise,weight:'',reps:'',rir:'',done:false};const wasDone=!!state.session.sets[k].done;state.session.sets[k][field]=val;if(field==='reps'&&String(val).trim()!==''&&!wasDone){state.session.sets[k].done=true;save();startRest(ex.rest);toast('Set logged · minimum rest started')}else save();workout();}
function completeSet(e,s){const k=keyFor(e,s);const ex=currentDay().exercises[e];if(!state.session.sets[k])state.session.sets[k]={exercise:ex.exercise,weight:'',reps:'',rir:'',done:false};if(state.session.sets[k].done){state.session.sets[k].done=false;save();workout();}else{state.session.sets[k].done=true;save();startRest(ex.rest);toast('Set logged · minimum rest started');workout();}}
function parseRest(txt){const m=String(txt).match(/(\d+)\s*-\s*(\d+)/);if(m)return (+m[1])*60;const n=String(txt).match(/(\d+)/);return n?+n[1]*60:90}
function startRest(txt){state.rest={running:true,end:Date.now()+parseRest(txt)*1000,seconds:parseRest(txt),display:state.rest.display||'normal'};primeAudio();save();workout();}
function startRestFixed(sec){state.rest={running:true,end:Date.now()+sec*1000,seconds:sec,display:state.rest.display||'normal'};primeAudio();save();workout();}
function cancelRest(){state.rest={running:false,end:0,seconds:0,display:state.rest.display||'normal'};save();workout();}
function setRestDisplay(mode){state.rest.display=mode;save();workout();}
function startRestTicker(){clearInterval(window.restTimer);window.restTimer=setInterval(()=>{if(!state.rest.running)return;if(Date.now()>=state.rest.end){state.rest.running=false;state.rest.seconds=0;save();notifyRestComplete();toast('REST COMPLETE');clearInterval(window.restTimer);workout();}else{const left=Math.ceil((state.rest.end-Date.now())/1000);const el=document.getElementById('restClock');if(el)el.textContent=fmtTime(left);}},250)}
function primeAudio(){try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;if(!window.restAudio)window.restAudio=new C();if(window.restAudio.state==='suspended')window.restAudio.resume();}catch(e){}}
function beep(){try{if(!window.restAudio)primeAudio();const c=window.restAudio;if(!c)return;const o=c.createOscillator(),g=c.createGain();o.frequency.value=880;g.gain.value=.0001;o.connect(g);g.connect(c.destination);const t=c.currentTime;g.gain.exponentialRampToValueAtTime(.18,t+.02);g.gain.exponentialRampToValueAtTime(.0001,t+.7);o.start(t);o.stop(t+.75);}catch(e){}}
async function requestRestNotifications(){if(!('Notification' in window)){toast('Notifications are not supported here');return}try{const p=await Notification.requestPermission();toast(p==='granted'?'Rest notifications enabled':'Notifications not enabled');primeAudio();}catch(e){toast('Notification permission unavailable')}}
function notifyRestComplete(){beep();if('Notification' in window&&Notification.permission==='granted'&&'serviceWorker' in navigator){navigator.serviceWorker.ready.then(r=>r.showNotification('Min-Max · Rest Complete',{body:'Your rest period is over. Time for your next set.',icon:'./icon-192.png',badge:'./icon-192.png',tag:'minmax-rest'})).catch(()=>{});}}
function restBar(){const r=state.rest;const display=r.display||'normal';if(display==='hidden')return `<div class="restbar rest-hidden"><div class="timer-row"><div><div class="stat">REST TIMER HIDDEN</div><div class="stat">${r.running?'Running in background':'Ready'}</div></div><div class="actions timer-buttons"><button class="smallbtn" onclick="setRestDisplay('small')">SHOW SMALL</button><button class="smallbtn" onclick="setRestDisplay('normal')">SHOW</button>${r.running?'<button class="smallbtn" onclick="cancelRest()">STOP</button>':''}</div></div></div>`;return `<div class="restbar ${display==='small'?'rest-small':''}"><div class="timer-row"><div><div class="stat">REST TIMER</div><div class="timer ${r.running?'running':''}" id="restClock">${r.running?fmtTime(Math.ceil((r.end-Date.now())/1000)):'00:00'}</div></div><div class="actions timer-buttons"><button class="smallbtn" onclick="startRestFixed(60)">1:00</button><button class="smallbtn" onclick="startRestFixed(120)">2:00</button><button class="smallbtn" onclick="startRestFixed(180)">3:00</button><button class="smallbtn" onclick="startRestFixed(240)">4:00</button><button class="smallbtn" onclick="startRestFixed(300)">5:00</button><button class="smallbtn plus" onclick="adjustRest(30)">+30s</button>${r.running?'<button class="smallbtn" onclick="cancelRest()">STOP</button>':''}<button class="smallbtn" onclick="setRestDisplay('small')">SMALL</button><button class="smallbtn" onclick="setRestDisplay('hidden')">HIDE</button><button class="smallbtn" onclick="requestRestNotifications()">🔔 NOTIFY</button></div></div></div>`}
function finishWorkout(){const s=state.session;if(!s)return;const elapsed=workoutElapsed();const sets=Object.values(s.sets||{}).filter(x=>x.done);const totalVol=sets.reduce((a,x)=>a+(+x.weight||0)*(+x.reps||0),0);s.end=Date.now();const record={...s,duration:elapsed,sets:s.sets,totalVolume:totalVol,date:new Date().toISOString()};state.history.push(record);state.active=false;state.session=null;state.rest={running:false,end:0,seconds:0,display:state.rest.display||'normal'};save();toast('Workout saved');setTimeout(()=>go('home'),300)}
function historyPage(){const hs=[...(state.history||[])].reverse();page('','Workout History',`<div class="actions" style="margin-bottom:12px"><button class="btn secondary" onclick="go('workout')">BACK TO WORKOUT</button></div><div class="card"><h3>Sessions</h3>${hs.length?hs.map(h=>`<div class="history-item"><div class="history-main"><strong>Week ${h.week} · ${esc(h.name)}</strong><span class="pill">${fmtTime(h.duration||0)}</span></div><div class="stat" style="margin-top:4px">${fmtDate(h.date)} · ${Object.values(h.sets||{}).filter(x=>x.done).length} sets · ${Math.round(h.totalVolume||0)} lb volume</div></div>`).join(''):'<div class="empty">No completed workouts yet.</div>'}</div>`,'workout')}
function progress(){const hs=state.history||[];const exerciseNames=[...new Set(hs.flatMap(h=>Object.values(h.sets||{}).map(x=>x.exercise)))];const selected=exerciseNames[0]||'Barbell Incline Press';const vals=hs.flatMap(h=>Object.values(h.sets||{}).filter(x=>x.exercise===selected&&x.weight&&x.reps).map(x=>({date:h.date,weight:+x.weight,reps:+x.reps,volume:(+x.weight||0)*(+x.reps||0)})));page('','Strength & Workout History',`<div class="card"><div class="stat">WORKOUTS</div><div class="big">${hs.length}</div><div class="stat" style="margin-top:5px">Track duration, volume, weights and reps over time.</div></div><div class="section-title"><h2>Exercise Progress</h2></div><select class="week-select" id="progressEx" onchange="progressExercise(this.value)">${exerciseNames.map(x=>`<option ${x===selected?'selected':''}>${esc(x)}</option>`).join('')}</select><div class="card" style="margin-top:12px"><h3>${esc(selected)}</h3>${simpleChart(vals)}</div><div class="section-title"><h2>Recent Workouts</h2></div><div class="card">${[...hs].reverse().slice(0,10).map(h=>`<div class="history-item"><div class="history-main"><strong>W${h.week} · ${esc(h.name)}</strong><span>${fmtTime(h.duration||0)}</span></div><div class="stat">${fmtDate(h.date)} · ${Math.round(h.totalVolume||0)} lb total volume</div></div>`).join('')||'<div class="empty">Finish a workout to see your progress.</div>'}</div><div class="section-title"><h2>Data</h2></div><div class="actions"><button class="btn secondary" onclick="exportData()">BACKUP DATA</button><button class="btn secondary" onclick="importData()">RESTORE DATA</button><button class="btn danger" onclick="resetData()">RESET</button></div>`,'progress')}
function progressExercise(name){progress();setTimeout(()=>{const el=document.getElementById('progressEx');if(el)el.value=name},0)}
function simpleChart(vals){if(!vals.length)return '<div class="empty">Log some sets for this exercise to see the chart.</div>';const max=Math.max(...vals.map(v=>v.weight)),min=Math.min(...vals.map(v=>v.weight)),w=640,h=180,p=22;const pts=vals.map((v,i)=>{const x=p+(vals.length===1?(w-2*p)/2:(i/(vals.length-1))*(w-2*p));const y=h-p-((v.weight-min)/Math.max(1,max-min))*(h-2*p);return [x,y]});const poly=pts.map(p=>p.join(',')).join(' ');return `<svg class="chart" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><polyline fill="none" stroke="#f2f3f5" stroke-width="4" points="${poly}"/>${pts.map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="#f2f3f5"/>`).join('')}</svg><div class="stat" style="margin-top:8px">${Math.round(min)}–${Math.round(max)} lb · ${vals.length} logged sets</div>`}
function programPage(){page('','Program Overview',`<div class="section-title"><h2>12 Weeks</h2><button class="smallbtn" onclick="chooseWeek()">Select Week</button></div><div class="list">${Array.from({length:12},(_,i)=>i+1).map(w=>`<div class="day-card" onclick="state.week=${w};state.day=0;save();go('home')"><div><div class="name">Week ${w} · Block ${w<=6?1:2}</div><div class="meta">${PROGRAM[String(w)].days.map(d=>d.name).join(' · ')}</div></div><span class="pill">${w===state.week?'CURRENT':'OPEN'}</span></div>`).join('')}</div><div class="card" style="margin-top:14px"><h3>Progression</h3><div class="stat">Log your working sets with weight, reps and RIR. Use the program's rep range and effort targets as written. Your history stays on the device unless you export a backup.</div></div>`,'program')}
function openInfoLookup(){showModal(`<button class="close" onclick="closeModal()">×</button><h2>ⓘ Quick Info & Lookup</h2><div class="lookup-wrap"><input id="infoSearch" class="lookup-input" type="search" placeholder="Search RIR, RDL, ROM, drop set..." oninput="filterInfoLookup(this.value)" autocomplete="off"></div><div id="infoLookupContent">${infoLookupItems()}</div>`)}
function infoLookupItems(){return `<div class="lookup-item" data-search="rir reps in reserve reps left failure"><strong>RIR — Reps In Reserve</strong><div class="stat">RIR 3 = about 3 reps left · RIR 2 = 2 reps left · RIR 1 = 1 rep left · RIR 0 = failure / zero reps left.</div></div><div class="lookup-item" data-search="wu warm up warm-up sets"><strong>WU</strong><div class="stat">Warm-up sets.</div></div><div class="lookup-item" data-search="rom range of motion stretched lengthened"><strong>ROM</strong><div class="stat">Range of motion.</div></div><div class="lookup-item" data-search="db dumbbell"><strong>DB</strong><div class="stat">Dumbbell.</div></div><div class="lookup-item" data-search="rdl romanian deadlift"><strong>RDL</strong><div class="stat">Romanian deadlift.</div></div><div class="lookup-item" data-search="pr personal record"><strong>PR</strong><div class="stat">Personal record.</div></div><div class="lookup-item" data-search="drop set intensity technique failure 25 percent"><strong>Drop Set</strong><div class="stat">After failure, reduce the weight by about 25% and go to failure again; repeat once more for 3 back-to-back sets total.</div></div><div class="lookup-item" data-search="lengthened partials intensity technique rom failure stretch"><strong>Lengthened Partials</strong><div class="stat">After full-ROM failure, continue with partial reps in the stretched/lengthened position until failure.</div></div><div class="lookup-item" data-search="myo reps myo-reps intensity technique five seconds 2 reps"><strong>Myo-Reps</strong><div class="stat">After failure, rest 5 seconds and attempt 2 more reps. Repeat until you cannot complete 2 full-ROM reps.</div></div><div class="lookup-item" data-search="weighted static hold intensity technique 30 seconds chest press bench"><strong>Weighted Static Hold</strong><div class="stat">After failure on the machine chest press (or dumbbell bench substitution), hold the bottom stretched position under tension for 30 seconds.</div></div><div class="lookup-item" data-search="progression increase load rep range"><strong>Progression</strong><div class="stat">When all working sets reach the top of the prescribed rep range, increase the load next session. If adding weight would drop you below the range, keep the same load and extend the rep range slightly.</div></div><div class="lookup-item" data-search="rest heavy compound isolation"><strong>Rest</strong><div class="stat">Heavy compounds generally use 3–5 minutes; lighter compounds and isolation work generally use 1–2 minutes.</div></div>`}
function filterInfoLookup(q){const query=(q||'').trim().toLowerCase();document.querySelectorAll('#infoLookupContent .lookup-item').forEach(el=>{el.style.display=!query||el.dataset.search.includes(query)?'block':'none'})}
function infoPage(){page('','Program Guide & Reference',`<div class="card"><h3>Program structure</h3><div class="stat">The Min-Max Program is a 12-week plan split into two 6-week blocks. It uses five training days: Upper 1, Lower 1, Upper 2, Lower 2, and Arms/Delts. Block 1 has no intensity techniques; Block 2 introduces last-set intensity techniques.</div></div><div class="section-title"><h2>RIR — Reps In Reserve</h2></div><div class="card"><div class="info-row"><strong>RIR 3</strong><span>About 3 reps left</span></div><div class="info-row"><strong>RIR 2</strong><span>2 reps left in the tank</span></div><div class="info-row"><strong>RIR 1</strong><span>1 rep left</span></div><div class="info-row"><strong>RIR 0</strong><span>Could not complete another rep / failure</span></div><p class="stat" style="margin-top:10px">For squat, barbell incline press, leg press, and Smith machine lunge, the program defines RIR 0 as having zero reps left without requiring an actual failed rep. For other exercises, RIR 0 means attempting and failing the final rep.</p></div><div class="section-title"><h2>Intensity techniques</h2></div><div class="list"><div class="card"><strong>Drop Set</strong><p class="stat">After failure, reduce the weight by about 25% and go to failure again; repeat once more for 3 back-to-back sets total.</p></div><div class="card"><strong>Lengthened Partials</strong><p class="stat">After full-ROM failure, continue with partial reps in the stretched/lengthened position until failure.</p></div><div class="card"><strong>Myo-Reps</strong><p class="stat">After failure, rest 5 seconds and attempt 2 more reps. Repeat the 5-second-rest/2-rep cycle until you cannot complete 2 full-ROM reps.</p></div><div class="card"><strong>Weighted Static Hold</strong><p class="stat">After failure on the machine chest press (or dumbbell bench substitution), hold the bottom stretched position under tension for 30 seconds.</p></div></div><div class="section-title"><h2>Program abbreviations</h2></div><div class="card"><div class="info-row"><strong>WU</strong><span>Warm-up sets</span></div><div class="info-row"><strong>RIR</strong><span>Reps in reserve</span></div><div class="info-row"><strong>ROM</strong><span>Range of motion</span></div><div class="info-row"><strong>DB</strong><span>Dumbbell</span></div><div class="info-row"><strong>RDL</strong><span>Romanian deadlift</span></div><div class="info-row"><strong>PR</strong><span>Personal record</span></div></div><div class="section-title"><h2>Progression rule</h2></div><div class="card"><p class="stat">When all working sets reach the top of the prescribed rep range, increase the load next session. If adding weight would drop you below the range, keep the same load and extend the rep range slightly.</p></div><div class="section-title"><h2>Rest guidance</h2></div><div class="card"><p class="stat">Heavy compound exercises generally use 3–5 minutes between sets. Lighter compounds and isolation work generally use 1–2 minutes. Warm-up sets use 0–60 seconds.</p></div><div class="section-title"><h2>Workout controls</h2></div><div class="card"><p class="stat"><strong>Pause</strong> freezes workout time so you can step away. <strong>Reset</strong> discards the unfinished session and its entries. <strong>Finish</strong> saves the session to history.</p></div>`,'info')}
function historyExercise(name){const hs=state.history.flatMap(h=>Object.values(h.sets||{}).filter(x=>x.exercise===name).map(x=>({...x,date:h.date,week:h.week}))).reverse();showModal(`<button class="close" onclick="closeModal()">×</button><h2>${esc(name)}</h2>${hs.length?hs.slice(0,30).map(x=>`<div class="history-item"><strong>W${x.week}</strong> · ${fmtDate(x.date)}<div class="stat">${x.weight} lb × ${x.reps} reps · RIR ${x.rir||'—'}</div></div>`).join(''):'<div class="empty">No history for this exercise yet.</div>'}`)}
function showModal(html){const d=document.createElement('div');d.className='modal-back';d.id='modal';d.innerHTML=`<div class="modal">${html}</div>`;document.body.appendChild(d)}function closeModal(){document.getElementById('modal')?.remove()}
function fmtDate(s){return new Date(s).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='minmax-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();URL.revokeObjectURL(a.href);toast('Backup downloaded')}
function importData(){const i=document.createElement('input');i.type='file';i.accept='.json,application/json';i.onchange=()=>{const f=i.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const x=JSON.parse(r.result);if(!x.history)throw Error();state=x;save();go('home');toast('Backup restored')}catch(e){toast('Invalid backup file')}};r.readAsText(f)};i.click()}
function resetData(){if(confirm('Reset all workout history and saved data? This cannot be undone unless you have a backup.')){localStorage.removeItem(KEY);state=load();home();toast('Data reset')}}
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
go(state.lastPage||'home');
